css:
.chapter-scope {
  --ink: #2c3e50;
  --muted: #7f8c8d;
  --accent: #2980b9;
  --warm: #e74c3c;
  --paper: #ecf0f1;
  --line: #bdc3c7;

  font-family: 'Georgia', 'Times New Roman', serif;
  font-size: 16px;
  line-height: 1.6;
  color: var(--ink);
  background-color: var(--paper);
  padding: 2rem;
  border: 1px solid var(--line);
  box-sizing: border-box;
  max-width: 100%;
}

.chapter-scope * {
  box-sizing: border-box;
}

.chapter-header {
  display: flex;
  justify-content: space-between;
  align-items: baseline;
  margin-bottom: 2rem;
  border-bottom: 2px solid var(--ink);
  padding-bottom: 1rem;
}

.chapter-title {
  font-size: 1.5rem;
  margin: 0;
  font-weight: bold;
  color: var(--ink);
}

.source-btn {
  background: transparent;
  border: 1px solid var(--muted);
  color: var(--muted);
  padding: 0.25rem 0.75rem;
  font-size: 0.85rem;
  cursor: pointer;
  font-family: monospace;
  transition: all 0.2s;
}

.source-btn:hover {
  border-color: var(--accent);
  color: var(--accent);
}

.dataset-workbench {
  display: flex;
  flex-wrap: wrap;
  gap: 2rem;
  justify-content: center;
  align-items: stretch;
  margin: 2rem 0;
  position: relative;
}

.dataset-pool {
  flex: 1;
  min-width: 280px;
  background: #fff;
  border: 1px solid var(--line);
  padding: 1.5rem;
  display: flex;
  flex-direction: column;
  align-items: center;
  text-align: center;
  transition: transform 0.4s ease, box-shadow 0.4s ease;
  position: relative;
}

.bb-pool {
  border-top: 4px solid var(--accent);
}

.msd-pool {
  border-top: 4px solid var(--muted);
}

.pool-label {
  font-size: 1.2rem;
  font-weight: bold;
  margin-bottom: 0.5rem;
  font-family: monospace;
}

.pool-meta {
  display: flex;
  gap: 0.5rem;
  margin-bottom: 1rem;
}

.meta-tag {
  background: var(--paper);
  padding: 0.2rem 0.5rem;
  font-size: 0.8rem;
  border: 1px solid var(--line);
  color: var(--muted);
}

.pool-count {
  font-size: 2rem;
  font-weight: bold;
  color: var(--ink);
  margin: 1rem 0;
}

.pool-detail {
  font-size: 0.9rem;
  color: var(--muted);
}

.interaction-core {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  min-width: 200px;
  gap: 1rem;
}

.overlap-visual {
  width: 100px;
  height: 100px;
  position: relative;
  margin: 1rem 0;
}

.overlap-zone {
  width: 100%;
  height: 100%;
  border-radius: 50%;
  border: 2px dashed var(--warm);
  background: rgba(231, 76, 60, 0.1);
  display: flex;
  align-items: center;
  justify-content: center;
  transition: all 0.5s ease;
}

.overlap-text {
  font-size: 0.7rem;
  color: var(--warm);
  font-weight: bold;
  opacity: 1;
  transition: opacity 0.3s;
}

.action-btn {
  background: var(--ink);
  color: #fff;
  border: none;
  padding: 0.75rem 1.5rem;
  font-size: 1rem;
  cursor: pointer;
  font-family: monospace;
  transition: background 0.2s;
}

.action-btn:hover {
  background: var(--accent);
}

.action-btn:disabled {
  background: var(--muted);
  cursor: not-allowed;
}

.status-message {
  font-size: 0.9rem;
  color: var(--warm);
  display: flex;
  align-items: center;
  gap: 0.5rem;
  opacity: 1;
  transition: opacity 0.3s;
}

.status-message.success {
  color: var(--accent);
  opacity: 0;
  position: absolute;
  pointer-events: none;
}

.status-icon {
  font-size: 1.2rem;
}

.evidence-note {
  margin-top: 2rem;
  padding: 1rem;
  background: #fff;
  border-left: 4px solid var(--muted);
  font-size: 0.9rem;
  color: var(--muted);
}

.evidence-note p {
  margin: 0.5rem 0;
}

/* State: Cleaned */
.chapter-scope.is-cleaned .overlap-zone {
  border-color: var(--accent);
  background: rgba(41, 128, 185, 0.1);
  transform: scale(0.8);
}

.chapter-scope.is-cleaned .overlap-text {
  opacity: 0;
}

.chapter-scope.is-cleaned #status-message {
  opacity: 0;
  display: none;
}

.chapter-scope.is-cleaned #status-success {
  opacity: 1;
  position: relative;
  pointer-events: auto;
}

.chapter-scope.is-cleaned #pool-bb {
  transform: translateX(-10px);
  box-shadow: -5px 5px 15px rgba(0,0,0,0.05);
}

.chapter-scope.is-cleaned #pool-msd {
  transform: translateX(10px);
  box-shadow: 5px 5px 15px rgba(0,0,0,0.05);
}

@media (max-width: 600px) {
  .dataset-workbench {
    flex-direction: column;
  }
  .interaction-core {
    order: -1;
    margin-bottom: 1rem;
  }
  .chapter-scope.is-cleaned #pool-bb,
  .chapter-scope.is-cleaned #pool-msd {
    transform: none;
  }
}

javascript:
(function() {
  'use strict';

  const scope = document.querySelector('.chapter-scope');
  if (!scope) return;

  const dedupBtn = document.getElementById('dedup-action');
  const statusMsg = document.getElementById('status-message');
  const statusSuccess = document.getElementById('status-success');
  const overlapVisual = document.getElementById('overlap-visual');

  function init() {
    if (!dedupBtn) return;

    dedupBtn.addEventListener('click', function() {
      // Perform deduplication simulation
      scope.classList.add('is-cleaned');
      dedupBtn.disabled = true;
      dedupBtn.textContent = '已去重';

      // Announce to screen readers
      if (statusSuccess) {
        statusSuccess.setAttribute('aria-live', 'polite');
      }
    });
  }

  // Ensure DOM is ready
  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', init);
  } else {
    init();
  }
})();
